"""Checks for routine_say.py's pure parts. Run: python .github/scripts/test_routine_say.py"""

import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import routine_say as rs  # noqa: E402

failed = []


def check(name, ok):
    print(("PASS " if ok else "FAIL ") + name)
    if not ok:
        failed.append(name)


check("a sort branch reads", rs.read_ref("claude/say-37-sort") == ("say", 37, "sort"))
check("a fix note branch reads", rs.read_ref("claude/say-5-fix") == ("say", 5, "fix"))
check("a fix branch reads", rs.read_ref("claude/fix-issue-12") == ("pr", 12, None))
check("other kinds are refused", rs.read_ref("claude/say-37-other") is None)
check("a branch with more after it is refused", rs.read_ref("claude/say-37-sort-x") is None)
check("a branch without a number is refused", rs.read_ref("claude/fix-issue-") is None)
check("main is refused", rs.read_ref("main") is None)
check("nothing is refused", rs.read_ref(None) is None)

ask = "<!-- eyecandy-sort: ask -->\nPhone: A player wants the FPS number bigger.\n\n**Why:** it fits."
no = "<!-- eyecandy-sort: no -->\nThank you for writing in. Eye Candy won't change for this one."
done = "<!-- eyecandy-fix: done -->\nThe FPS number is bigger now. It ships in version 1.1.1 once released."
check("an ask is fine", rs.check_comment("sort", ask) is None)
check("a no is fine", rs.check_comment("sort", no) is None)
check("a fix note is fine", rs.check_comment("fix", done) is None)
check("a fix marker on a sort branch is refused", rs.check_comment("sort", done) is not None)
check("text before the marker is refused", rs.check_comment("sort", "hi\n" + ask) is not None)
check("no text is refused", rs.check_comment("sort", "") is not None)

for bad in ["See https://example.com", "see www.example.com", "thanks @someone", "mail me a@b.com",
            "Generated with a tool", "Generated by a tool", "Co-Authored-By: x", "Claude wrote this",
            "Anthropic", "an AI tool", "the bot said", "a routine sorted it", "an LLM"]:
    check(f"refused: {bad}", rs.check_comment("sort", ask + "\n" + bad) is not None)
for fine in ["the bottom of the window", "a rain effect", "the maintainer", "Refs #12", "email me never"]:
    check(f"allowed: {fine}", rs.refusal(fine) is None)
check("too long is refused", rs.refusal("a" * (rs.MAX_TEXT + 1)) is not None)

owner = "PortalPi"
mine = {"user": {"login": rs.fp.BOT}, "body": ask, "html_url": "u"}
check("an earlier sort comment by the workflow is found", rs.posted_before("sort", [mine], owner) is mine)
check("an earlier one by the maintainer is found", rs.posted_before("sort", [{**mine, "user": {"login": owner}}], owner) is not None)
check("a stranger's marker does not block", rs.posted_before("sort", [{**mine, "user": {"login": "someone"}}], owner) is None)
check("a sort comment does not block a fix note", rs.posted_before("fix", [mine], owner) is None)
check("no comments, nothing found", rs.posted_before("sort", [], owner) is None)

check("subject and body split", rs.split_message("fix(ui): a thing\n\nWhy it was.\nRefs #3\n") == ("fix(ui): a thing", "Why it was.\nRefs #3"))
check("subject only", rs.split_message("fix(ui): a thing") == ("fix(ui): a thing", ""))

print("ALL PASS" if not failed else f"{len(failed)} FAILED")
sys.exit(1 if failed else 0)
